'use strict';
const KEY='daily-reps-engine-v2';
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const newProfile=name=>({id:crypto.randomUUID(),name,equipment:['Dumbbells','1x Kettlebell','Resistance Bands','Bodyweight'],bans:[],mode:'rotation',weeklyTarget:5,rotationIndex:0,schedule:['Push','Pull','Lower'].map(type=>({type,custom:null})),history:[],session:null});
let state=readStoredState();if(!state){const p=newProfile('My profile');state={profiles:[p],active:p.id};}
let tab='Workout',day=(new Date().getDay()+6)%7,openAlts=new Set(),previewSwaps={},audioCtx=null,storageWarning=false,setupDraft=null,focusMode=false;
const profile=()=>state.profiles.find(x=>x.id===state.active);
function persist(){if(!saveState(state)&&!storageWarning){storageWarning=true;toast('Storage unavailable. Export a backup in Settings.');}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display='none',4000);}
function norm(s){return s.toLowerCase().replace(/\bdb\b/g,'dumbbell').replace(/\bkb\b/g,'kettlebell').replace(/[^a-z0-9]+/g,' ').trim();}
function allowed(m,p=profile()){return m&&m.equipment.every(x=>p.equipment.includes(x))&&!p.bans.some(b=>norm(m.name+' '+(m.tags||'')).includes(norm(b).replace(/^no /,'')));}
function circuit(d=day,p=profile()){const plan=p.schedule[d];if(plan.type==='Rest')return [];const used=new Set();return PRESETS[plan.type].map((ids,i)=>{const custom=plan.custom?.[i];let candidates=custom?[custom.main,custom.alt].filter(Boolean):ids.map(id=>MOVES[id]);let main=candidates.find(m=>allowed(m,p)&&!used.has(m.name));if(!main&&!custom){const group=MOVES[ids[0]].group;main=Object.values(MOVES).find(m=>m.group===group&&allowed(m,p)&&!used.has(m.name));}if(main)used.add(main.name);const alt=candidates.find(m=>allowed(m,p)&&m.name!==main?.name)||(!custom?Object.values(MOVES).find(m=>allowed(m,p)&&m.group===main?.group&&m.name!==main?.name):null);return {main:main?clone(main):null,alt:alt?clone(alt):null};});}
function activeSession(){return profile().session;}
function hasActive(){const s=activeSession();return s&&!s.finished;}
function currentCircuit(){const s=activeSession();if(s&&s.day===day&&!s.finished)return s.circuit;const override=profile().workoutOverrides;const rows=override?.date===localDate()&&override.slots?.[day]?clone(override.slots[day]):circuit();for(const r of rows)if(r.main)r.main.weightKg=savedLoad(r.main);return rows;}
function movePattern(m){const known=Object.values(MOVES).find(x=>x.name===m?.name);return m?.pattern||known?.pattern||m?.group||known?.group||null;}
function moveGroup(m){return m?.group||Object.values(MOVES).find(x=>x.name===m?.name)?.group||null;}
function swapRelation(main,alt){return movePattern(main)&&movePattern(main)===movePattern(alt)?'Similar movement pattern':'Different movement · different stimulus';}
function alternativesFor(r,i,rows=currentCircuit()){
 const group=moveGroup(r.main)||MOVES[PRESETS[profile().schedule[day].type]?.[i]?.[0]]?.group;
 const explicit=[...(r.alts||[]),r.alt].filter(Boolean),candidates=[...explicit,...Object.values(MOVES).filter(m=>m.group===group&&!m.libraryAlias)];
 const occupied=new Set(rows.filter((_,n)=>n!==i).map(r=>r.main?.name)),names=new Set([r.main?.name]);
 return candidates.filter(m=>{if(!allowed(m)||names.has(m.name)||occupied.has(m.name)||moveGroup(m)!==group)return false;names.add(m.name);return true;}).sort((a,b)=>Number(movePattern(b)===movePattern(r.main))-Number(movePattern(a)===movePattern(r.main)));
}
function swapExercise(i,choice){const s=activeSession();if(s&&!s.finished&&s.day!==day)return;if(s?.running&&remaining(s)<=0){finish(s);return;}const rows=currentCircuit(),r=rows[i];if(!r)return;const choices=alternativesFor(r,i,rows),replacement=choices[choice];if(!replacement)return;const old=clone(r.main);r.main=clone(replacement);r.main.weightKg=savedLoad(r.main);r.alt=old;r.alts=old?[old]:[];if(s&&!s.finished){s.circuit=rows;s.echoInvalid=true;}else{const p=profile();if(p.workoutOverrides?.date!==localDate())p.workoutOverrides={date:localDate(),slots:{}};p.workoutOverrides.slots[day]=clone(rows);}persist();render();toast('Movement swapped for this workout.');}
function remaining(s=activeSession()){return !s?1200000:s.running?Math.max(0,s.endAt-Date.now()):s.remaining;}
function streak(){const dates=new Set(profile().history.map(h=>h.date));let d=new Date();d.setHours(12,0,0,0);if(!dates.has(localDate(d)))d.setDate(d.getDate()-1);let n=0;while(dates.has(localDate(d))){n++;d.setDate(d.getDate()-1);}return n;}
function options(items,value){return items.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');}
function unitFor(m){return /^\s*[\d–—. -]+\s*(sec|seconds|s)\s*$/i.test(m?.reps||'')?'sec':'reps';}
function repEntries(s){return s?.repEntries||[];}
function countTotal(entries,unit='reps'){return entries.filter(e=>e.unit===unit).reduce((sum,e)=>sum+e.count,0);}
function savedLoad(m){const value=profile().loads?.['move:'+m?.name];return value!=null?value:m?.equipment?.every(e=>e==='Bodyweight')?0:null;}
function sameEntry(a,b){return a.name===b.name&&a.unit===b.unit&&(a.weightKg??null)===(b.weightKg??null);}
function sessionEntries(s){const entries=clone(repEntries(s));for(const r of s.circuit){const m=r.main,row={name:m?.name,unit:unitFor(m),weightKg:m?.weightKg??null,count:0};if(m&&!entries.some(e=>sameEntry(e,row)))entries.push(row);}return entries;}
function loadCaption(e){return e.weightKg==null?'Load not recorded':e.weightKg===0?'No external load':`${e.weightKg} kg total external load`;}
function loadField(m,i,s){return m?`<label class="load-field" for="load-${i}">Total external load (kg) <input id="load-${i}" data-load="${i}" inputmode="decimal" type="number" min="0" max="1000" step="0.25" placeholder="Optional" value="${esc(m.weightKg??savedLoad(m)??'')}" ${s?.running?'':' '}></label><p class="small muted load-help">Both dumbbells combined. One weight: enter that weight. Bodyweight: 0. Bands: leave blank.</p>`:'';}
function saveLoad(i,raw){const rows=currentCircuit(),m=rows[i]?.main;if(!m)return;const weight=raw.trim()===''?null:Number(raw);if(weight!==null&&(!Number.isFinite(weight)||weight<0||weight>1000)){toast('Enter a load between 0 and 1000 kg, or leave it blank.');render();return;}profile().loads??={};const session=activeSession();if(session&&!session.finished&&session.day===day){if(session.running&&remaining(session)<=0){finish(session);return;}if((m.weightKg??null)!==weight){m.weightKg=weight;session.echoInvalid=true;}}profile().loads['move:'+m.name]=weight;persist();}
function breakdown(entries){return `<div class="rep-breakdown">${entries.map(e=>`<div class="rep-line"><span>${esc(e.name)}<small class="load-caption">${esc(loadCaption(e))}</small></span><strong>${e.count.toLocaleString()} <small>${e.unit}</small></strong></div>`).join('')}</div>`;}
function addReps(i,amount){const s=activeSession();if(!s||s.finished||s.day!==day||![1,5,10].includes(amount))return;if(s.running&&remaining(s)<=0){finish(s);return;}const m=s.circuit[i]?.main;if(!m)return;s.repEntries??=[];s.repLog??=[];const unit=unitFor(m);const row={name:m.name,unit,weightKg:m.weightKg??null};let entry=s.repEntries.find(e=>sameEntry(e,row));if(!entry){entry={...row,count:0};s.repEntries.push(entry);}entry.count+=amount;s.repLog.push({name:m.name,unit,weightKg:m.weightKg??null,amount,slot:i,at:1200000-remaining(s)});persist();render();}
function undoReps(i){const s=activeSession();if(!s||s.finished||s.day!==day)return;if(s.running&&remaining(s)<=0){finish(s);return;}const index=s.repLog?.findLastIndex(e=>e.slot===i)??-1;if(index<0)return;const [last]=s.repLog.splice(index,1);const entry=s.repEntries.find(e=>sameEntry(e,last));entry.count=Math.max(0,entry.count-last.amount);persist();render();}
function allRepEntries(){const totals=new Map();for(const h of profile().history)for(const e of h.repEntries||[]){const key=JSON.stringify([e.name,e.unit,e.weightKg??null]);const row=totals.get(key)||{...e,count:0};row.count+=e.count;totals.set(key,row);}return [...totals.values()].sort((a,b)=>b.count-a.count);}
function repOverview(){const entries=allRepEntries(),tracked=profile().history.filter(h=>Array.isArray(h.repEntries)).length;return `<section class="section" style="margin-top:24px"><div class="eyebrow">ALL COMPLETED SESSIONS</div><h2 style="margin-top:8px">${countTotal(entries).toLocaleString()} total reps</h2>${countTotal(entries,'sec')?`<p>${countTotal(entries,'sec')} seconds of holds, tracked separately</p>`:''}<p class="small">${tracked} sessions with rep tracking. Earlier sessions have no rep counts.</p>${entries.length?breakdown(entries):'<p style="margin-top:16px">Log reps during your next workout to build your exercise overview.</p>'}</section>`;}
function metrics(){const n=profile().history.length;return `<div class="metric-row"><div class="metric"><strong>${n}</strong><span>Sessions completed</span></div><div class="metric"><strong>${n*20}<small style="font-size:14px"> min</small></strong><span>Training time</span></div><div class="metric"><strong>${streak()}<small style="font-size:14px"> days</small></strong><span>Current streak</span></div></div>`;}
function week(){const p=profile();if(isRotation()){const next=nextWorkoutIndex();return `<section class="rotation-summary"><div><div class="eyebrow">${hasActive()?'CURRENT WORKOUT':'NEXT WORKOUT'}</div><h2>${esc(p.schedule[hasActive()?activeSession().day:next].type)}</h2><p class="small muted">Rolling rotation · ${weeklyTarget()} sessions per week</p></div>${day!==next&&!hasActive()?'<button data-action="next-workout">Open next workout</button>':''}</section><div class="rotation-queue" aria-label="Workout sequence">${p.schedule.map((_,offset)=>{const i=(next+offset)%p.schedule.length;return `<button class="queue-item ${day===i?'selected':''}" data-action="day" data-i="${i}" aria-pressed="${day===i}"><span>${offset===0?'Next':`Then ${offset+1}`}</span><strong>${esc(p.schedule[i].type)}</strong></button>`;}).join('')}</div>${monthCalendar()}`;}return `<div class="week" aria-label="Select workout day">${p.schedule.map((plan,i)=>`<button class="day ${day===i?'selected':''}" data-action="day" data-i="${i}" aria-pressed="${day===i}"><span>${DAYS[i].slice(0,3)}</span><strong>${esc(plan.type)}</strong></button>`).join('')}</div>${monthCalendar()}`;}
function uiIcon(name){const paths={Workout:'<path d="M6 4v16M3 7v10M18 4v16M21 7v10M6 12h12"/>',Builder:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',Progress:'<path d="M4 4v16h16M8 15l4-5 4 2 4-6"/>',Settings:'<path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1"/><circle cx="12" cy="12" r="5"/>',focus:'<path d="M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};return `<svg class="ui-icon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.Workout}</svg>`;}
function render(){ensureScheduleMode();const p=profile();if(!p.schedule[day])day=defaultWorkoutIndex();document.querySelector('#app').innerHTML=`<header><div class="logo" aria-hidden="true">20</div><div class="brand">Daily Reps<small>20-minute workouts</small></div><button class="setup-button" data-action="setup">${uiIcon('Settings')}<span>Setup</span></button><select class="profile" id="profile-select" aria-label="Active profile">${pOptions()}</select></header><main class="shell ${focusMode&&tab==='Workout'?'focus-mode':''}"><nav aria-label="Main navigation">${['Workout','Builder','Progress','Settings'].map(t=>`<button data-action="tab" data-tab="${t}" class="${tab===t?'active':''}" aria-current="${tab===t?'page':'false'}">${uiIcon(t)}<span>${t}</span></button>`).join('')}</nav>${storageWarning?'<div class="storage-alert">Local storage is unavailable. Export a backup from Settings before closing this page.</div>':''}${tab==='Workout'?workout():tab==='Builder'?builder():tab==='Progress'?progress():tab==='Setup'?setupView():settings()}<footer><span id="runtime-status">${esc(runtimeStatus())}</span><span>Saved on this browser · ${esc(p.name)} · <a href="daily-reps-source.zip" download style="color:inherit">Download source</a></span></footer></main>`;tick();paintRuntimeStatus();}
function pOptions(){return state.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===state.active?'selected':''}>${esc(p.name)}</option>`).join('');}
function workout(){const p=profile(),plan=p.schedule[day],s=activeSession(),here=s&&s.day===day&&!s.finished,rows=currentCircuit(),blocked=rows.some(r=>!r.main),other=hasActive()&&!here;if(here&&focusMode)return trainingView(s,rows);return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">TRAINING</div><h1>Workout</h1><p class="muted">${esc(profile().name)} · ${weeklyTarget()} sessions / week · Equipment filters applied</p></div><button data-action="focus" class="focus-button">${uiIcon('focus')}<span>${focusMode?'Exit focus':'Focus mode'}</span></button></div>${week()}${weekGoal()}<p class="small muted">One movement per card. Reps and seconds are tracked separately.</p>${isRotation()&&day!==nextWorkoutIndex()&&!here?'<div class="alert">Previewing a later workout. <button data-action="next-workout">Open next workout</button></div>':''}${other?`<div class="alert">You have a ${esc(s.type)} session in progress. <button data-action="resume-view">Return to session</button></div>`:''}${plan.type==='Rest'?`<div class="empty"><div class="symbol">◌</div><h2>Rest day</h2><p>No circuit scheduled for ${isRotation()?`Workout ${day+1}`:DAYS[day]}. Keep this day free or choose a workout in the builder.</p><button data-action="tab" data-tab="Builder">Edit this day</button></div>`:`<div class="work-grid"><aside class="timer-panel"><div class="eyebrow">THE 20-MINUTE CIRCUIT</div><div class="timer-top"><span class="tag" style="border-color:#20291540;color:var(--ink)">${plan.type.toUpperCase()}</span><span class="small" id="timer-status">Not started</span></div><div class="timer-dial"><div class="timer-dial-inner"><div class="timer" id="timer" role="timer" aria-label="Time remaining">20:00</div><div class="timer-label">remaining</div></div></div><div class="progress" role="progressbar" aria-label="Session progress" aria-valuemin="0" aria-valuemax="1200" aria-valuenow="0"><i id="timer-bar"></i></div><div class="timer-controls"><button class="start" id="start-btn" data-action="start" ${blocked||other||(isRotation()&&day!==nextWorkoutIndex()&&!here)?'disabled':''}>Start session</button><button data-action="reset" aria-label="Reset session" ${!here?'disabled':''}>Reset</button></div><div class="roundline"><span>SESSION TOTAL</span><strong aria-live="polite">${countTotal(here?repEntries(s):[])} reps</strong></div>${here&&countTotal(repEntries(s),'sec')?`<div class="small" style="margin-top:8px">+ ${countTotal(repEntries(s),'sec')} sec of holds</div>`:''}<p class="timer-note">Cycle through all five moves, then repeat. The clock keeps running between rounds.</p>${echoPanel(here?s:null,rows)}</aside><section><div class="circuit-head"><div><h2>${plan.type==='Upper'?'Upper body':plan.type} circuit</h2><p class="muted small">${FOCUS[plan.type]}</p></div><button data-action="tab" data-tab="Builder" class="small" ${hasActive()?'disabled':''}>Edit</button></div>${blocked?'<div class="alert">Some moves are unavailable with your filters. Adjust your equipment or edit the empty slots before starting.</div>':''}${rows.map((r,i)=>exercise(r,i,here?s:null)).join('')}<p class="small muted" style="padding:10px 0">Add reps with +1, +5 or +10 after each set. For one-sided moves, count both sides together. Holds are logged in seconds.</p></section></div>`}${metrics()}`;}
function groupLabel(m){return MUSCLE_GROUPS[moveGroup(m)]||'Custom movement';}
function slotGroup(i,r){return moveGroup(r.main)||MOVES[PRESETS[profile().schedule[day].type]?.[i]?.[0]]?.group;}
function libraryForGroup(group){return Object.values(MOVES).filter(m=>m.group===group&&!m.libraryAlias);}
function workoutGroups(){return [...new Set((PRESETS[profile().schedule[day].type]||[]).map(ids=>MOVES[ids[0]].group))];}
function exercise(r,i,s){
 const m=r.main,alts=alternativesFor(r,i),unit=unitFor(m),group=slotGroup(i,r),total=libraryForGroup(group).length;
 const count=repEntries(s).filter(e=>e.name===m?.name&&e.unit===unit).reduce((n,e)=>n+e.count,0);
 return `<article class="exercise exercise-${esc(group||'custom')}"><div class="exercise-main"><span class="number">0${i+1}</span><div class="exercise-copy"><span class="muscle-label">${esc(MUSCLE_GROUPS[group]||'Custom movement')}</span><h3>${esc(m?.name||'Choose an available movement')}</h3><div class="meta"><span class="rep-target">${esc(m?.reps||'Choose a movement below')}</span>${m?`<span class="equipment-label">${esc(m.equipment.join(' + '))}</span>`:''}</div></div><div class="rep-count" aria-live="polite"><strong>${count}</strong><span>${unit}</span></div></div>${loadField(m,i,s)}<div class="rep-controls">${[1,5,10].map(n=>`<button data-action="add-reps" data-i="${i}" data-amount="${n}" aria-label="Add ${n} ${unit} to ${esc(m?.name||'exercise')}" ${!s||!m?'disabled':''}>+${n}${unit==='sec'?'s':''}</button>`).join('')}<button class="undo-reps" data-action="undo-reps" data-i="${i}" aria-label="Undo last entry for exercise ${i+1}" ${!s?.repLog?.some(e=>e.slot===i)?'disabled':''}>Undo</button></div><button class="alt-toggle" data-action="alt" data-i="${i}" aria-controls="choices-${i}" aria-expanded="${openAlts.has(i)}">${openAlts.has(i)?'− Hide exercise library':`+ Form & choose exercise · ${alts.length} options`}</button>${openAlts.has(i)?`<div class="alt" id="choices-${i}">${m?movementGuide(m):''}<div class="library-heading"><div class="eyebrow">${esc(MUSCLE_GROUPS[group]||'Exercise')} LIBRARY</div><p class="small muted">${total} exercises in this group. ${alts.length} alternatives match your equipment and exclusions and are not already in this workout. Similar patterns appear first; other patterns change the stimulus.</p></div><label for="search-${i}">Find an exercise</label><input type="search" id="search-${i}" data-exercise-search="${i}" placeholder="Search name, equipment or pattern" autocomplete="off"><p class="small muted" data-search-count="${i}" role="status">${alts.length} options</p><div class="exercise-options">${alts.map((alt,k)=>`<div class="alternative-option" data-exercise-option="${i}" data-search="${esc(norm(alt.name+' '+alt.equipment.join(' ')+' '+alt.pattern+' '+groupLabel(alt)))}"><div><span class="muscle-label">${esc(groupLabel(alt))}</span><h3>${esc(alt.name)}</h3><p class="small muted">${esc(alt.reps)} · ${esc(alt.equipment.join(' + '))}</p><span class="swap-kind">${esc(alt.pattern)} · ${esc(swapRelation(m,alt))}</span><p class="small muted form-cues">${esc(alt.description)}</p></div><button data-action="swap" data-i="${i}" data-choice="${k}" aria-label="Choose ${esc(alt.name)}">Choose</button></div>`).join('')}</div><p class="small muted" data-search-empty="${i}" ${alts.length?'hidden':''}>No matching exercises. Try another search or update your equipment and exclusions in Settings.</p><p class="small muted">Choices apply to this workout. Save them as your routine below to use them next time.</p><button data-action="remember-workout" ${hasActive()?'disabled':''}>Save choices as my ${esc(profile().schedule[day].type)} routine</button>${hasActive()?'<p class="small muted">Finish or reset your session before saving a routine.</p>':''}</div>`:''}</article>`;
}

function builder(){const plan=profile().schedule[day],rows=circuit();return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">PLAN YOUR WEEK</div><h1>Edit workouts</h1><p class="muted">Edit your workout circuits. Setup controls the schedule and sequence.</p></div></div>${week()}${hasActive()?'<div class="alert">Pause and reset your active session before changing workouts or equipment.</div>':''}<form id="builder-form"><fieldset ${hasActive()?'disabled':''} style="border:0;padding:0;margin:0"><div class="section"><div class="form-grid"><div><label for="routine-type">${isRotation()?`Workout ${day+1}`:DAYS[day]} routine</label><select id="routine-type">${options(isRotation()?TYPES.filter(t=>t!=='Rest'):TYPES,plan.type)}</select></div><div><label>Circuit size</label><div style="padding:11px 0">${plan.type==='Rest'?'Recovery day · no exercises':'5 exercises · 20 minutes'}</div></div></div>${plan.type==='Rest'?'<p style="margin-top:18px">This day is set aside for recovery.</p>':rows.map((r,i)=>builderRow(r,i)).join('')}</div>${plan.type!=='Rest'?'<div class="builder-actions"><button type="button" data-action="restore">Restore preset</button><button type="submit" class="primary">Save five-exercise circuit</button></div>':''}</fieldset></form>`;}
function builderRow(r,i){const main=r.main||{name:'',reps:'10–12 reps',description:'',equipment:['Bodyweight']},alt=r.alt||{name:'',equipment:['Bodyweight']};const groups=workoutGroups();const all=Object.values(MOVES).filter(m=>allowed(m)&&groups.includes(m.group)&&!m.libraryAlias);return `<div class="builder-row"><div class="number">0${i+1}</div><div><label for="library-${i}">Choose a movement for this workout, or enter your own below</label><select id="library-${i}" data-library="${i}"><option value="">Custom / current movement</option>${groups.map(g=>`<optgroup label="${esc(MUSCLE_GROUPS[g])}">${all.filter(m=>m.group===g).map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.pattern)}</option>`).join('')}</optgroup>`).join('')}</select><div class="form-grid"><div class="field"><label for="name-${i}">Exercise name</label><input id="name-${i}" name="name-${i}" value="${esc(main.name)}" required maxlength="100"></div><div class="field"><label for="reps-${i}">Reps / duration</label><input id="reps-${i}" name="reps-${i}" value="${esc(main.reps)}" required maxlength="60"></div></div><div class="field"><label for="group-${i}">Muscle group</label><select id="group-${i}" name="group-${i}">${groups.map(g=>`<option value="${g}" ${g===(moveGroup(main)||slotGroup(i,r))?'selected':''}>${esc(MUSCLE_GROUPS[g])}</option>`).join('')}</select></div><div class="field"><label for="desc-${i}">Form cues</label><textarea id="desc-${i}" name="desc-${i}" maxlength="500">${esc(main.description)}</textarea></div><div class="field"><label for="eq-${i}">Required equipment (select all that apply)</label><select multiple id="eq-${i}" name="eq-${i}" size="3">${EQUIPMENT.map(e=>`<option ${main.equipment.includes(e)?'selected':''}>${e}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="alt-${i}">Alternative name (optional)</label><input id="alt-${i}" name="alt-${i}" value="${esc(alt.name)}" maxlength="100"></div><div class="field"><label for="alteq-${i}">Alternative equipment</label><select multiple id="alteq-${i}" name="alteq-${i}" size="3">${EQUIPMENT.map(e=>`<option ${alt.equipment.includes(e)?'selected':''}>${e}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label for="altreps-${i}">Alternative reps</label><input id="altreps-${i}" name="altreps-${i}" value="${esc(alt.reps||'10–12 reps')}" maxlength="60"></div><div class="field"><label for="altdesc-${i}">Alternative form cues</label><input id="altdesc-${i}" name="altdesc-${i}" value="${esc(alt.description||'')}" maxlength="500"></div></div></div></div>`;}
function progress(){const p=profile(),dates=new Set(p.history.map(h=>h.date));const days=Array.from({length:28},(_,i)=>{let d=new Date();d.setDate(d.getDate()-27+i);return localDate(d);});return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">WORKOUT HISTORY</div><h1>Progress</h1><p class="muted">Completed workouts, reps and training time.</p></div></div>${metrics()}${repOverview()}<div class="section" style="margin-top:24px"><h2>Your last 28 days</h2><div class="dots">${days.map(d=>`<div class="dot ${dates.has(d)?'trained':''}" title="${d}: ${dates.has(d)?'Trained':'No session'}" role="img" aria-label="${d}: ${dates.has(d)?'Trained':'No session'}"></div>`).join('')}</div><p class="small">Blue = completed session · Rest days do not count toward a consecutive-day streak.</p></div><div class="section"><h2>Session history</h2>${p.history.length?p.history.slice().reverse().map(h=>`<div class="history"><div><strong>${esc(h.type)} circuit</strong><div class="small muted">${new Date(h.finishedAt).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}</div></div><div style="text-align:right"><strong style="color:var(--lime)">20 min ✓</strong><div class="small muted">${Array.isArray(h.repEntries)?`${countTotal(h.repEntries)} reps${countTotal(h.repEntries,'sec')?` · ${countTotal(h.repEntries,'sec')} sec`: ''}`:'Reps not recorded'}</div></div></div>${Array.isArray(h.repEntries)?`<details class="history-details"><summary>Reps per exercise</summary>${breakdown(h.repEntries)}</details>`:''}`).join(''):'<div class="empty" style="border:0;padding:36px 12px"><h3>No completed workouts yet.</h3><p>Completed 20-minute workouts appear here.</p><button class="primary" data-action="tab" data-tab="Workout">Go to workout</button></div>'}</div>`;}
function settings(){const p=profile();return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">PREFERENCES</div><h1>Settings</h1><p class="muted">Every preset and alternative follows these filters.</p></div></div><div class="wide">${hasActive()?'<div class="alert">Reset the current session to change equipment or excluded movements.</div>':''}<section class="section"><h2>Available equipment</h2><p class="small">Choose what you can use. Ab Wheel is an optional accessory.</p><div class="chips">${EQUIPMENT.map(e=>`<button class="chip ${p.equipment.includes(e)?'selected':''}" data-action="equipment" data-value="${e}" aria-pressed="${p.equipment.includes(e)}" ${hasActive()?'disabled':''}>${p.equipment.includes(e)?'✓ ': '+ '}${e}</button>`).join('')}</div></section><section class="section"><h2>Excluded movements</h2><p class="small">Name a movement or a category. Matching exercise names are filtered out.</p><div class="chips">${['Barbell Squat','Bench Press','Pull-up','Slams'].map(b=>`<button class="chip ${p.bans.includes(b)?'selected':''}" data-action="ban" data-value="${b}" ${hasActive()?'disabled':''}>${p.bans.includes(b)?'✓ ': '+ '}${b}</button>`).join('')}</div><form id="ban-form" style="display:flex;gap:8px;margin-top:16px"><input aria-label="Movement to exclude" name="ban" placeholder="e.g. overhead press" required maxlength="80" ${hasActive()?'disabled':''}><button ${hasActive()?'disabled':''}>Exclude</button></form><div class="chips">${p.bans.map(b=>`<button class="chip selected" data-action="ban" data-value="${esc(b)}" ${hasActive()?'disabled':''}>${esc(b)} ×</button>`).join('')}</div></section>${reliabilitySettings()}<section class="section"><h2>Finish sound</h2><p class="small">A short chime marks the finish. Keep this page open and the screen awake: browser sound is not a reliable lock-screen alarm.</p><button data-action="toggle-sound" aria-pressed="${p.preferences?.sound!==false}">Sound ${p.preferences?.sound===false?'off':'on'}</button><button data-action="test-sound" ${p.preferences?.sound===false?'disabled':''} style="margin-top:16px">Test finish sound</button></section><section class="section"><h2>Local profiles</h2><p class="small">Each profile has its own schedule, filters and history. Profiles live in this browser, without accounts or cross-device sync.</p><form id="profile-form" style="display:flex;gap:8px;margin-top:18px"><input name="name" aria-label="New profile name" placeholder="New profile name" required maxlength="40"><button>Create</button></form><form id="rename-form" style="display:flex;gap:8px;margin-top:12px"><input name="name" aria-label="Rename current profile" value="${esc(p.name)}" required maxlength="40"><button>Rename</button></form><button data-action="delete-profile" class="danger-button" style="margin-top:16px">Delete this profile</button></section></div>`;}
function modal(html){const m=document.querySelector('#modal');m.innerHTML=html;if(!m.open)m.showModal();}
function confirmReset(){modal('<h2>Reset this session?</h2><p>The timer and logged reps will be cleared. An unfinished session does not count toward your progress.</p><div class="builder-actions"><button data-action="close">Keep session</button><button class="primary" data-action="confirm-reset">Reset session</button></div>');}
async function setupAudio(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();}catch{}}
function finish(s){if(s.finished)return;s.finished=true;s.running=false;s.remaining=0;const finishedAt=s.endAt||Date.now();const p=profile();if(!p.history.some(h=>h.id===s.id))p.history.push({id:s.id,date:localDate(new Date(finishedAt)),finishedAt,type:s.type,repEntries:sessionEntries(s),totalReps:countTotal(repEntries(s)),totalSeconds:countTotal(repEntries(s),'sec'),fingerprint:s.fingerprint||null,repLog:clone(s.repLog||[]),echoEligible:!s.echoInvalid});if(s.mode==='rotation'&&!s.rotationAdvanced){profile().rotationIndex=(s.day+1)%profile().schedule.length;s.rotationAdvanced=true;day=profile().rotationIndex;}if(profile().workoutOverrides?.slots)delete profile().workoutOverrides.slots[s.day];persist();playFinishTune();syncWakeLock();focusMode=false;document.body.classList.add('flash');setTimeout(()=>document.body.classList.remove('flash'),3000);render();modal(`<div class="celebrate"><div class="medal">✓</div><div class="eyebrow">20-MINUTE SESSION COMPLETE</div><h2 style="margin-top:12px">Workout complete · ${countTotal(repEntries(s))} reps</h2>${countTotal(repEntries(s),'sec')?`<p>+ ${countTotal(repEntries(s),'sec')} seconds of holds</p>`:''}${breakdown(sessionEntries(s))}<p>${esc(s.type)} circuit complete. Your session is saved.<br><strong>${streak()}-day streak · ${p.history.length} sessions</strong></p><button class="primary" data-action="view-progress">See my progress</button></div>`);}
function tick(){const s=activeSession();updateEcho();if(s?.running&&remaining(s)<=0&&!s.finished){finish(s);return;}const el=document.querySelector('#timer');if(!el)return;const here=s&&s.day===day;const left=here?remaining(s):1200000;const sec=Math.ceil(left/1000);el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;document.querySelector('#timer-bar').style.width=(1-left/1200000)*100+'%';document.querySelector('.timer-dial').style.setProperty('--timer-angle',`${(1-left/1200000)*360}deg`);document.querySelector('.progress').setAttribute('aria-valuenow',String(1200-sec));document.querySelector('#timer-status').textContent=here?(s.finished?'Session complete':s.running?'Running':'Paused'):'Not started';document.querySelector('#start-btn').textContent=here?(s.finished?'Start workout':s.running?'Pause':'Resume'):'Start workout';}
function start(){let s=activeSession();if(isRotation()&&day!==nextWorkoutIndex()&&!hasActive())return;if(s&&!s.finished&&s.day!==day)return;if(!s||s.finished){const rows=currentCircuit();if(rows.length!==5||rows.some(r=>!r.main))return;s={id:crypto.randomUUID(),day,mode:profile().mode||'fixed',type:profile().schedule[day].type,circuit:clone(rows),repEntries:[],repLog:[],fingerprint:circuitFingerprint(rows),echoInvalid:false,remaining:1200000,running:false,finished:false,activeSlot:0};profile().session=s;}if(s.running){s.remaining=remaining(s);if(s.remaining<=0){finish(s);return;}s.running=false;}else{s.endAt=Date.now()+s.remaining;s.running=true;setupAudio().then(()=>{syncFinishAudio();paintRuntimeStatus();});}focusMode=profile().preferences?.compact!==false;persist();render();syncSessionRuntime();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,i=Number(b.dataset.i),p=profile(),s=activeSession();if(a==='test-sound'){setupAudio().then(()=>{playFinishTune();syncFinishAudio();paintRuntimeStatus();});return;}if(a==='setup'){openSetup();return;}if(a==='focus'){focusMode=!focusMode;render();return;}if(a==='echo-toggle'){p.echoOff=!p.echoOff;persist();render();return;}if(a==='tab'){tab=b.dataset.tab;openAlts.clear();render();}if(a==='day'){day=i;previewSwaps={};openAlts.clear();render();}if(a==='resume-view'){day=s.day;tab='Workout';render();}if(a==='next-workout'){day=nextWorkoutIndex();render();}if(a==='start')start();if(a==='reset')confirmReset();if(a==='close')document.querySelector('#modal').close();if(a==='confirm-reset'){cancelFinishAudio();focusMode=false;p.session=null;previewSwaps={};persist();document.querySelector('#modal').close();render();syncSessionRuntime();}if(a==='alt'){openAlts.has(i)?openAlts.delete(i):openAlts.add(i);render();}if(a==='add-reps')addReps(i,Number(b.dataset.amount));if(a==='undo-reps')undoReps(i);if(a==='swap')swapExercise(i,Number(b.dataset.choice||0));if(a==='equipment'&&!hasActive()){p.equipment=p.equipment.includes(b.dataset.value)?p.equipment.filter(x=>x!==b.dataset.value):[...p.equipment,b.dataset.value];previewSwaps={};p.workoutOverrides=null;persist();render();}if(a==='ban'&&!hasActive()){toggleBan(b.dataset.value);render();}if(a==='restore'&&!hasActive()){p.schedule[day].custom=null;p.workoutOverrides=null;persist();render();toast('Preset restored with your equipment filters.');}if(a==='view-progress'){document.querySelector('#modal').close();tab='Progress';render();}});
function toggleBan(value){const p=profile();p.bans=p.bans.includes(value)?p.bans.filter(x=>x!==value):[...p.bans,value];previewSwaps={};p.workoutOverrides=null;persist();}
document.addEventListener('change',e=>{if(e.target.id==='profile-select'){cancelFinishAudio();focusMode=false;state.active=e.target.value;setupDraft=null;if(tab==='Setup')tab='Workout';day=activeSession()&&!activeSession().finished?activeSession().day:defaultWorkoutIndex();previewSwaps={};persist();render();syncSessionRuntime();}if(e.target.id==='routine-type'&&!hasActive()){profile().schedule[day]={type:e.target.value,custom:null};profile().workoutOverrides=null;previewSwaps={};persist();render();}if(e.target.dataset.library!==undefined){const i=e.target.dataset.library,m=MOVES[e.target.value];if(!m)return;document.getElementById(`group-${i}`).value=m.group;for(const [field,value]of Object.entries({name:m.name,reps:m.reps,desc:m.description}))document.getElementById(`${field}-${i}`).value=value;for(const o of document.getElementById(`eq-${i}`).options)o.selected=m.equipment.includes(o.value);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='profile-form'){cancelFinishAudio();focusMode=false;const name=f.get('name').trim();if(!name)return;const p=newProfile(name);state.profiles.push(p);state.active=p.id;day=defaultWorkoutIndex();persist();render();syncSessionRuntime();toast('New profile created.');}if(form.id==='rename-form'){const name=f.get('name').trim();if(name){profile().name=name;persist();render();toast('Profile renamed.');}}if(form.id==='ban-form'&&!hasActive()){const v=f.get('ban').trim();if(norm(v).replace(/^no /,'').length<2){toast('Enter a movement name.');return;}if(!profile().bans.includes(v))toggleBan(v);render();}if(form.id==='builder-form'&&!hasActive()){let rows=[];for(let i=0;i<5;i++){const main={name:f.get(`name-${i}`).trim(),reps:f.get(`reps-${i}`).trim(),description:f.get(`desc-${i}`).trim(),equipment:f.getAll(`eq-${i}`)};const altName=f.get(`alt-${i}`).trim();const alt=altName?{name:altName,reps:f.get(`altreps-${i}`).trim(),description:f.get(`altdesc-${i}`).trim(),equipment:f.getAll(`alteq-${i}`)}:null;if(!main.name||!main.reps||!main.equipment.length||(alt&&!alt.equipment.length)){toast('Each move needs a name, reps and equipment.');return;}if(!allowed(main)||(alt&&!allowed(alt))){toast(`Exercise ${i+1} conflicts with your equipment or exclusions.`);return;}if(/[+]/.test(main.name)||/\d\s*(extensions|raises).*\+|\+.*\d/.test(main.reps)){toast('Use one movement per slot. Log reps or seconds, not a combination.');return;}const known=Object.values(MOVES).find(m=>m.name===main.name);main.group=known?.group||f.get(`group-${i}`)||MOVES[PRESETS[profile().schedule[day].type][i][0]].group;if(!workoutGroups().includes(main.group)){toast('Choose a muscle group that belongs to this workout.');return;}main.pattern=known?.pattern||main.group;if(alt){const other=Object.values(MOVES).find(m=>m.name===alt.name);alt.group=other?.group||main.group;alt.pattern=other?.pattern||alt.group;if(alt.group!==main.group){toast('Choose an alternative from the same movement family.');return;}}rows.push({main,alt});}profile().schedule[day].custom=rows;profile().workoutOverrides=null;previewSwaps={};persist();tab='Workout';render();toast('Your five-exercise circuit is saved.');}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.profiles?.some(p=>p.id===next.active)){state=migrateState(validateState(next));mirrorState(JSON.stringify(state));day=hasActive()?activeSession().day:defaultWorkoutIndex();render();syncSessionRuntime();}}catch{}}});


// Filter existing nodes so typing never loses keyboard focus or changes choice indices.
document.addEventListener('input',e=>{
 const i=e.target.dataset.exerciseSearch;if(i===undefined)return;
 const terms=norm(e.target.value).split(' ').filter(Boolean);let visible=0;
 for(const node of document.querySelectorAll(`[data-exercise-option="${i}"]`)){
  node.hidden=!terms.every(term=>node.dataset.search.includes(term));if(!node.hidden)visible++;
 }
 document.querySelector(`[data-search-count="${i}"]`).textContent=`${visible} options`;
 document.querySelector(`[data-search-empty="${i}"]`).hidden=visible>0;
});
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action="remember-workout"]');if(!button||button.disabled||hasActive())return;
 const rows=currentCircuit();if(rows.some(r=>!r.main)){toast('Choose an exercise for all five slots first.');return;}
 profile().schedule[day].custom=clone(rows);profile().workoutOverrides=null;persist();render();toast('Routine saved for future workouts.');
});
